from pathlib import Path
import re

p = Path('app/src/main/assets/index.html')
h = p.read_text(encoding='utf-8')

# Remove older post-v8 viewport/chrome experiments.
h = re.sub(r'<style id="vnext-viewport-fix">.*?</style>', '', h, flags=re.S)

# Approved v8 microcopy/icons.
h = h.replace('<span>✎</span>Notes', '<span>▤</span>Notes')
h = h.replace('<div class="section-label">Your books</div>', '<div class="section-label">All books</div>')
h = h.replace('<div class="topbar"><h1>Notes</h1><div></div></div>',
              "<div class=\"topbar\"><h1>Notes</h1><button class=\"iconbtn\" onclick=\"showToast('Search notes')\">⌕</button></div>")
h = h.replace('<div class="vnext-period-title" id="vnextPeriodTitle">This week</div>',
              "<div class=\"v8-date-row\"><button type=\"button\" onclick=\"showToast('Previous period')\">‹</button><span id=\"vnextPeriodTitle\">This week</span><button type=\"button\" onclick=\"showToast('Next period')\">›</button></div>")

# Approved v8 settings IA; keep existing MyReader functions and Drive IDs.
settings_start = h.index('<section id="settings" class="screen">')
reader_start = h.index('<section id="reader" class="screen">', settings_start)
settings = r"""  <section id="settings" class="screen">
    <div class="topbar"><h1>Settings</h1><div></div></div>
    <div class="settings-scroll">
      <div class="settings-group"><div class="group-title">Reading appearance</div><div class="settings-card simple">
        <button class="setting-link" onclick="openReadingSettingsPreview()"><span class="sl-icon">Aa</span><span class="sl-copy"><b>Reader font</b><small>EPUB and TXT reading font</small></span><span class="settings-badge">Georgia</span><span class="sl-arrow">›</span></button>
        <button class="setting-link" onclick="openReadingSettingsPreview()"><span class="sl-icon">◐</span><span class="sl-copy"><b>Reading theme</b><small>Reader page background</small></span><span class="settings-badge">Paper</span><span class="sl-arrow">›</span></button>
        <button class="setting-link" onclick="toggleImmersivePreference()"><span class="sl-icon">↔</span><span class="sl-copy"><b>Tap to hide controls</b><small>Center tap hides or shows reader controls</small></span><span id="vnextTapHideBadge" class="settings-badge">On</span></button>
        <button class="setting-link" onclick="vnextCycleTurnMethod()"><span class="sl-icon">⇆</span><span class="sl-copy"><b>Page turn method</b><small>Choose how you move between pages</small></span><span id="vnextTurnMethodBadge" class="settings-badge">Tap + swipe</span><span class="sl-arrow">›</span></button>
        <button class="setting-link" onclick="vnextCycleTurnEffect()"><span class="sl-icon">▱</span><span class="sl-copy"><b>Page turn effect</b><small>Instant is lightest; Book flip feels like a real page</small></span><span id="vnextTurnEffectBadge" class="settings-badge">Instant</span><span class="sl-arrow">›</span></button>
        <button class="setting-link" onclick="toggleEinkReader()"><span class="sl-icon">↯</span><span class="sl-copy"><b>E-Ink friendly mode</b><small>Reduce animation and redraws</small></span><span id="einkSettingsBadge" class="settings-badge">On</span></button>
      </div></div>
      <div class="settings-group"><div class="group-title">PDF & Comics</div><div class="settings-card simple">
        <button class="setting-link" onclick="setPdfDefaultFromSettings('width')"><span class="sl-icon">▤</span><span class="sl-copy"><b>Default PDF view</b><small>Applied when opening PDF</small></span><span id="pdfDefaultBadge" class="settings-badge">Fit width</span><span class="sl-arrow">›</span></button>
        <button class="setting-link" onclick="cyclePdfRenderDefault()"><span class="sl-icon">⌗</span><span class="sl-copy"><b>Auto crop margins</b><small>Trim blank edges on scanned pages</small></span><span class="settings-badge">On</span></button>
        <button class="setting-link" onclick="showToast('Crop preference is remembered per book')"><span class="sl-icon">◩</span><span class="sl-copy"><b>Remember crop per book</b><small>Keep each book's crop choice</small></span><span class="settings-badge">On</span></button>
        <button class="setting-link" onclick="cyclePdfDirectionDefault()"><span class="sl-icon">↔</span><span class="sl-copy"><b>Comic direction</b><small>CBZ/CBR page order</small></span><span id="pdfDirectionBadge" class="settings-badge">L → R</span><span class="sl-arrow">›</span></button>
      </div></div>
      <div class="settings-group"><div class="group-title">Library & Storage</div><div class="settings-card simple">
        <button class="setting-link" onclick="chooseBooks()"><span class="sl-icon">＋</span><span class="sl-copy"><b>Add books</b><small>Uses the existing MyReader import flow</small></span><span class="settings-badge">EPUB/PDF/CBZ/CBR/TXT</span><span class="sl-arrow">›</span></button>
        <div class="setting-link"><span class="sl-icon">✦</span><span class="sl-copy"><b>Read book metadata</b><small>Title, author and embedded cover</small></span><span class="settings-badge">On</span></div>
        <button class="setting-link" onclick="showToast('Reading cache')"><span class="sl-icon">⌫</span><span class="sl-copy"><b>Reading cache</b><small>Temporary PDF and cover data</small></span><span class="settings-badge">Local</span><span class="sl-arrow">›</span></button>
      </div></div>
      <div class="settings-group"><div class="group-title">Sync & backup</div><div class="settings-card simple" id="googleDriveSyncSettings">
        <button class="setting-link" id="driveConnectBtn" type="button"><span class="sl-icon">☁</span><span class="sl-copy"><b>Google Drive folder</b><small id="driveSyncSubtitle">Choose a folder once</small></span><span id="driveSyncStatus" class="settings-badge">Offline</span><span class="sl-arrow">›</span></button>
        <button class="setting-link" id="driveSyncNowBtn" type="button"><span class="sl-icon">↕</span><span class="sl-copy"><b>Sync now</b><small>Progress, notes, highlights & settings</small></span><span id="driveLastSync" class="settings-badge">Never synced</span><span class="sl-arrow">›</span></button>
      </div></div>
      <div class="settings-group"><div class="group-title">About</div><div class="settings-card simple"><div class="setting-link"><span class="sl-icon">♡</span><span class="sl-copy"><b>MyReader</b><small>Full vNext prototype v8 · by vlafoor ♡</small></span><span class="settings-badge">Preview</span></div></div></div>
    </div>
    <nav class="bottomnav"><button class="navitem" onclick="openScreen('library')"><span>▥</span>Library</button><button class="navitem" onclick="openScreen('stats')"><span>⌁</span>Stats</button><button class="navitem" onclick="openScreen('notes')"><span>▤</span>Notes</button><button class="navitem active"><span>⚙</span>Settings</button></nav>
  </section>

  """
h = h[:settings_start] + settings + h[reader_start:]

css = r"""<style id="v8-reference-ui">
:root{--bg:#deddd7;--paper:#fbfaf6;--ink:#20231f;--muted:#777a72;--line:#d8d6cf;--accent:#526f61;--accent-soft:#e4ece6;--chip:#efede6;--danger:#a24a43;--shadow:0 16px 38px rgba(35,42,37,.14)}
html,body{margin:0!important;height:100%!important;overflow:hidden!important;background:var(--bg)!important;color:var(--ink)!important;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important}#app{width:100%!important;height:100dvh!important;min-height:0!important;margin:0!important;background:var(--paper)!important;position:relative!important;overflow:hidden!important}.screen{background:var(--paper)!important}
.topbar{flex:0 0 auto!important;display:flex!important;align-items:center!important;justify-content:space-between!important;gap:10px!important;padding:18px 16px 10px!important;background:var(--paper)!important;border-bottom:1px solid rgba(216,214,207,.85)!important;box-shadow:0 3px 8px rgba(32,35,31,.025)!important;z-index:60!important}.topbar h1{font:700 27px/1.05 Georgia,serif!important;letter-spacing:0!important;margin:0!important;display:flex!important;flex-direction:column!important;gap:3px!important}.topbar h1::before{content:'MYREADER';font:800 10px/1 Inter,system-ui,sans-serif!important;letter-spacing:.14em!important;color:var(--muted)!important}#stats .topbar h1::before{content:'READING'}
.iconbtn{width:38px!important;height:38px!important;border:1px solid var(--line)!important;border-radius:12px!important;background:var(--paper)!important;display:grid!important;place-items:center!important;font-size:21px!important;line-height:1!important}.searchbox{margin:12px 16px 8px!important;height:44px!important;border:1px solid var(--line)!important;border-radius:14px!important;background:#fff!important;display:flex!important;align-items:center!important;gap:9px!important;padding:0 12px!important;color:var(--muted)!important}.searchbox input{border:0!important;outline:0!important;min-width:0!important;flex:1!important;background:transparent!important;font-size:14px!important}
.chips,.vnext-note-filters{display:flex!important;gap:7px!important;overflow:auto!important;padding:4px 16px 12px!important}.chip,.vnext-note-filters button{flex:0 0 auto!important;border:1px solid var(--line)!important;background:var(--paper)!important;border-radius:999px!important;padding:8px 12px!important;font-size:12px!important;font-weight:700!important;color:var(--ink)!important}.chip.active,.vnext-note-filters button.active{background:var(--ink)!important;border-color:var(--ink)!important;color:#fff!important}
.scroll,.simple-scroll,.settings-scroll{flex:1 1 auto!important;min-height:0!important;overflow-y:auto!important;overscroll-behavior:contain!important;-webkit-overflow-scrolling:touch!important;padding:0 16px 86px!important;background:var(--paper)!important}.section-label{font-size:14px!important;letter-spacing:.08em!important;text-transform:uppercase!important;color:var(--muted)!important;font-weight:800!important;margin:7px 0 9px!important}.continue-card{margin:0 0 17px!important;border:1px solid #cfd9d1!important;background:var(--accent-soft)!important;border-radius:17px!important;padding:12px!important;box-shadow:none!important}.continue-card .mini-cover{width:58px!important;height:80px!important;border-radius:7px!important}.continue-info h3{font-size:13px!important}.continue-info p{font-size:11px!important}.book-grid{grid-template-columns:repeat(3,1fr)!important;gap:16px 11px!important;padding:0 0 26px!important}.cover-wrap{border-radius:9px!important;box-shadow:0 3px 8px rgba(0,0,0,.06)!important}.book-name{font-size:11px!important;margin:6px 0 2px!important;-webkit-line-clamp:2!important}.book-author{font-size:9px!important;margin-top:0!important}.bottomnav{position:absolute!important;left:0!important;right:0!important;bottom:0!important;height:70px!important;flex:0 0 70px!important;border-top:1px solid var(--line)!important;background:rgba(251,250,246,.99)!important;display:grid!important;grid-template-columns:repeat(4,1fr)!important;z-index:80!important}.navitem{border:0!important;background:transparent!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:3px!important;font-size:9px!important;color:var(--muted)!important;min-width:0!important}.navitem.active{color:var(--accent)!important;font-weight:800!important}.navitem span{font-size:19px!important;line-height:1!important;margin:0!important}
.vnext-stats-scroll{padding:8px 16px 86px!important}.vnext-stats-summary{border:1px solid var(--line)!important;border-radius:17px!important;padding:15px 8px!important;background:#fff!important;display:grid!important;grid-template-columns:repeat(3,1fr)!important;margin:0!important}.vnext-stats-summary>div{text-align:center!important;border-right:1px solid var(--line)!important}.vnext-stats-summary>div:last-child{border-right:0!important}.vnext-stats-summary b{font:700 20px Georgia,serif!important}.vnext-stats-summary span{font-size:9px!important;color:var(--muted)!important}.vnext-period{display:flex!important;margin:15px 0 12px!important;padding:3px!important;border:1px solid var(--line)!important;border-radius:12px!important}.vnext-period button{flex:1!important;border:0!important;background:transparent!important;padding:9px!important;border-radius:9px!important;font-size:12px!important;font-weight:800!important}.vnext-period button.active{background:var(--ink)!important;color:#fff!important}.v8-date-row{display:flex!important;justify-content:center!important;align-items:center!important;gap:16px!important;margin:6px 0 14px!important;font-size:12px!important;font-weight:800!important}.v8-date-row button{border:0!important;background:transparent!important;font-size:19px!important;color:var(--muted)!important}.vnext-chart-card{border:1px solid var(--line)!important;border-radius:17px!important;background:#fff!important;padding:14px 12px!important}.vnext-chart{height:210px!important;border-bottom:1px solid var(--line)!important;background:repeating-linear-gradient(to top,transparent 0,transparent 51px,#efeee9 52px)!important}.vnext-insight{background:var(--accent-soft)!important}
#notesList{padding:0 16px 86px!important}.note-card{margin:0 0 11px!important;border:1px solid var(--line)!important;border-radius:15px!important;background:#fff!important;padding:12px!important}.note-card blockquote{margin:8px 0!important;font:15px/1.45 Georgia,serif!important}
.settings-scroll{padding:5px 16px 86px!important}.settings-group{margin:12px 0 17px!important}.group-title{font-size:10px!important;text-transform:uppercase!important;letter-spacing:.13em!important;color:var(--muted)!important;margin:0 4px 7px!important;font-weight:800!important}.settings-card{margin:0!important;border:1px solid var(--line)!important;border-radius:16px!important;background:#fff!important;overflow:hidden!important}.setting-link{width:100%!important;min-height:58px!important;padding:10px 13px!important;display:flex!important;align-items:center!important;gap:11px!important;border:0!important;border-bottom:1px solid var(--line)!important;background:#fff!important;text-align:left!important}.setting-link:last-child{border-bottom:0!important}.sl-icon{width:32px!important;height:32px!important;border-radius:9px!important;background:var(--chip)!important;display:grid!important;place-items:center!important;flex:0 0 auto!important}.sl-copy{min-width:0!important;flex:1!important}.sl-copy b{display:block!important;font-size:13px!important}.sl-copy small{display:block!important;font-size:10px!important;color:var(--muted)!important;margin-top:2px!important}.settings-badge{font-size:11px!important;color:var(--muted)!important;white-space:nowrap!important;background:transparent!important;border:0!important;padding:0!important}.sl-arrow{color:var(--muted)!important;font-size:20px!important}
#reader{background:#fbfaf6!important}.reader-head{flex:0 0 55px!important;height:55px!important;padding:7px 10px!important;display:flex!important;align-items:center!important;justify-content:center!important;border-bottom:1px solid var(--line)!important;background:var(--paper)!important;position:relative!important;z-index:35!important}.reader-head-left{position:absolute!important;left:9px!important;top:7px!important;height:40px!important;display:flex!important;align-items:center!important;gap:7px!important;min-width:0!important}.reader-head-left .iconbtn{width:38px!important;height:38px!important;border:0!important;background:transparent!important;font-size:25px!important}.reader-device-info{font:700 8px/1 Inter,system-ui!important;color:var(--muted)!important}.reader-head .bookhead{position:static!important;transform:none!important;width:min(58%,230px)!important;max-width:min(58%,230px)!important;text-align:center!important;font:700 13px Georgia,serif!important;color:var(--ink)!important}.vnext-reader-footer{flex:0 0 101px!important;height:101px!important;display:block!important;padding:0!important;border:0!important;background:var(--paper)!important}.vnext-progress-pill{position:absolute!important;left:11px!important;right:11px!important;bottom:69px!important;height:32px!important;border:1px solid var(--line)!important;border-radius:12px!important;background:rgba(251,250,246,.97)!important;display:flex!important;align-items:center!important;gap:8px!important;padding:8px 9px!important;font:9px Inter,sans-serif!important;color:var(--muted)!important}.vnext-progress-line{flex:1!important;height:4px!important;background:rgba(0,0,0,.12)!important}.vnext-reader-tools{position:absolute!important;left:0!important;right:0!important;bottom:0!important;height:69px!important;background:var(--paper)!important;border-top:1px solid var(--line)!important;display:grid!important;grid-template-columns:repeat(6,1fr)!important}.vnext-reader-tools button{border:0!important;background:transparent!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:3px!important;font-size:7px!important;color:var(--muted)!important;padding:0!important}.vnext-reader-tools button span{font-size:18px!important;line-height:1!important;color:var(--ink)!important}.reader-page{flex:1!important;min-height:0!important;padding:22px 21px 28px!important;background:#fbfaf6!important;color:var(--reader-ink,#20231f)!important}#reader.chrome-hidden .reader-head{flex:0 0 55px!important;height:55px!important;padding:7px 10px!important;opacity:0!important;visibility:hidden!important;pointer-events:none!important;transform:none!important}#reader.chrome-hidden .vnext-reader-footer{flex:0 0 101px!important;height:101px!important;opacity:0!important;visibility:hidden!important;pointer-events:none!important}#reader.chrome-hidden .reader-page{padding-top:22px!important;padding-bottom:28px!important}
.vnext-sheet-backdrop{background:rgba(30,32,29,.34)!important}.vnext-sheet{background:var(--paper)!important;border-radius:20px 20px 0 0!important;border-top:1px solid var(--line)!important;box-shadow:0 -16px 35px rgba(0,0,0,.14)!important;max-height:72vh!important;padding:0!important}
</style>"""

h = h.replace('</head>', css + '\n</head>', 1)
h = re.sub(r'^(?:\\n)+', '', h)
p.write_text(h, encoding='utf-8')

# Version this separately from the experimental v0.3.5 build.
gradle = Path('app/build.gradle')
g = gradle.read_text(encoding='utf-8')
g = re.sub(r'versionCode\s+\d+', 'versionCode 31', g, count=1)
g = re.sub(r"versionName\s+['\"][^'\"]+['\"]", "versionName '0.3.6-v8-ui'", g, count=1)
gradle.write_text(g, encoding='utf-8')

assert 'id="v8-reference-ui"' in h
assert 'Full vNext prototype v8' in h
assert '<span>▤</span>Notes' in h
assert '#reader.chrome-hidden .reader-head{flex:0 0 55px!important' in h
for demo in ['The Quiet Edge','Ubur-Ubur Lembur','Teka-Teki Gambar Aneh','Makhluk Bumi','Catatan Pembunuhan','The Let Them Theory','Sapiens']:
    assert demo not in h, f'Demo book leaked into APK: {demo}'
